const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M15 3.13a4 4 0 0 1 0 7.75M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',wallet:'M20 7H5a2 2 0 0 1 0-4h13v4m2 0a1 1 0 0 1 1 1v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5m18 7h-5v5h5m-4-2.5h.1',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',back:'m15 18-6-6 6-6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M6 18 18 6',check:'m5 12 4 4L19 6',clock:'M12 8v4l3 2M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM12 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6Z',search:'m21 21-5-5M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Z',more:'M5 12h.01M12 12h.01M19 12h.01',phone:'M22 16.9v3a2 2 0 0 1-2.18 2A19.8 19.8 0 0 1 3.1 5.18 2 2 0 0 1 5.1 3h3a2 2 0 0 1 2 1.72c.1.96.34 1.9.69 2.8a2 2 0 0 1-.45 2.11L9.1 10.9a16 16 0 0 0 4 4l1.27-1.23a2 2 0 0 1 2.11-.45c.9.35 1.84.59 2.8.69a2 2 0 0 1 2.72 2.99Z',share:'M12 16V2m-5 5 5-5 5 5M5 12v8a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-8',copy:'M9 9h12v12H9ZM5 15H3V3h12v2',scan:'M3 8V3h5m8 0h5v5m0 8v5h-5M8 21H3v-5M7 7h3v3H7Zm7 0h3v3h-3ZM7 14h3v3H7Zm7 0h3v3h-3Z',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Zm-4 10 3 3 5-6',alert:'M12 8v5m0 4h.01M10.3 3.8 2 18a2 2 0 0 0 1.7 3h16.6a2 2 0 0 0 1.7-3L13.7 3.8a2 2 0 0 0-3.4 0Z',info:'M12 11v6m0-10h.01M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Z',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v2m0 16v2M2 12h2m16 0h2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4m0-14.2-1.4 1.4M6.3 17.7l-1.4 1.4',moon:'M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z',monitor:'M3 3h18v14H3Zm5 18h8m-4-4v4',download:'M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5',logout:'M9 5H3v14h6m6-14 6 7-6 7M8 12h13',wifi:'M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0m-4 4h.01',battery:'M2 6h17v12H2Zm20 4v4M5 9h11v6H5Z',layers:'m12 2 10 5-10 5L2 7Zm-10 10 10 5 10-5M2 17l10 5 10-5',ticket:'M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4Zm12 0v3m0 3v2m0 3v3',minus:'M5 12h14',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM9 2h6l1 3 3 1 3 5v2l-3 5-3 1-1 3H9l-1-3-3-1-3-5v-2l3-5 3-1Z'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.info}"/></svg>`;
const button=(label,action,cls='',attrs='')=>`<button class="button ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const textButton=(label,action,attrs='')=>`<button class="text-button" data-action="${action}" ${attrs}>${label}</button>`;
const chip=(text,tone='',i='')=>`<span class="chip ${tone}">${i?icon(i):''}${text}</span>`;
const notice=(text,tone='',i='info')=>`<div class="inline-note ${tone}">${icon(i)}<span>${text}</span></div>`;
const brand=()=>'<div class="wordmark"><img class="logo" src="assets/logo.svg" alt="">skipit<span class="sr-only">SkipIt</span></div>';
const field=(label,name,type='text',value='',extra='',hint='')=>`<label class="form-field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${extra}>${hint?`<small>${hint}</small>`:''}</label>`;
const phoneField=(value='',name='phone')=>`<label class="form-field"><span>Mobile number</span><div class="phone-field"><span>+91</span><input name="${name}" type="tel" inputmode="numeric" autocomplete="tel-national" placeholder="98200 12345" value="${esc(value)}" pattern="[6-9][0-9 ]{9,11}" required maxlength="12" aria-label="10-digit Indian mobile number"></div></label>`;
const initials=s=>s.split(' ').map(x=>x[0]).slice(0,2).join('');
const phone=n=>'+91 '+n.slice(0,5)+' '+n.slice(5);
const seed=[['Aanya Shah',4,'Women','in',true],['Rohan Mehta',2,'Couple','in',true],['Sana Khan',3,'Women','in',true],['Arjun Kapoor',1,'Stag','in',true],['Diya Patel',4,'Women','in',true],['Kabir Sethi',2,'Couple','in',true],['Ishaan Rao',2,'Stag','in',true],['Meera Joshi',4,'Women','coming',true],['Vihaan Desai',1,'Stag','coming',false],['Anika Bhat',2,'Couple','coming',true],['Dev Malhotra',1,'Stag','coming',true],['Ira Sen',3,'Women','coming',true],['Yash Jain',2,'Stag','coming',false],['Nisha Dsouza',4,'Women','coming',true],['Rehan Ali',2,'Stag','coming',false],['Tara Menon',3,'Women','coming',true]];
const initialData=()=>({guests:seed.map((g,i)=>({id:i+1,name:g[0],size:g[1],type:g[2],status:g[3],paid:g[4],phone:'900001'+String(i+1).padStart(4,'0'),source:i===10?'direct':'online',token:'demo-'+(i+1),time:'11:42 pm'})),staff:[{name:'Sameer Patil',phone:'9000020001'},{name:'Akash Singh',phone:'9000020002'}],events:[],closed:false,cancelled:false,profile:{name:'Aditya Rao',upi:'aditya.demo@upi'},guestPass:null});
let db;try{db=JSON.parse(localStorage.getItem('skipit-demo-v1'))||initialData()}catch{db=initialData()}
const save=()=>{try{localStorage.setItem('skipit-demo-v1',JSON.stringify(db))}catch{toast('Changes last for this visit only. Storage is unavailable.')}};
const catalog={promoter:{home:'Overview',events:'Events',create:'Create event',event:'Live event',add:'Add guest',staff:'Door staff',book:'Guest book',money:'Money',settings:'Settings',auth:'Sign in',otp:'Verify code'},bouncer:{tonight:'Tonight',scanner:'Scanner',verdict:'Scan verdict',auth:'Sign in',otp:'Verify code'},guest:{event:'Event & signup',pass:'Private pass',checkout:'Online payment'},system:{tokens:'Design tokens',components:'Components',assets:'Logo & icons',coverage:'Screen inventory'}};
const states={home:['default','empty','loading','error'],events:['default','empty','loading','error'],event:['default','list-closed','cancelled','loading','error'],create:['default','validation','loading','error'],add:['default','success','error'],staff:['default','empty','loading','error'],book:['default','empty','loading','error'],money:['default','zero-owed','empty','loading','error'],settings:['default','saved','error'],auth:['default','unknown','error'],otp:['default','wrong-code','expired','loading','error'],tonight:['default','not-open','not-added','empty','loading','error'],scanner:['default','camera-denied','offline'],verdict:['let-in','payment-due','scan-again','already-used','not-on-list','expired'],pass:['on-list','payment-due','checked-in','cancelled','event-cancelled','night-over','loading','error'],checkout:['default','processing','success','failed'],tokens:['default'],components:['default'],assets:['default'],coverage:['default']};
const guestEventStates=['default','returning','link-inactive','list-closed','option-full','already-listed','night-ended','no-connection','event-cancelled','loading','error'];
let ui={role:'promoter',screen:'home',state:'default',theme:localStorage.getItem('skipit-theme')||'system',period:'month',filter:'All',search:'',entry:'Women',size:1,signPhone:'',resendAt:0,selectedGuest:null,selectedEvent:null,scanGuest:8};
let cameraStream=null,modalPrevious=null;
const screens=()=>catalog[ui.role];
const stateList=()=>ui.role==='guest'&&ui.screen==='event'?guestEventStates:states[ui.screen]||['default'];
const pretty=s=>s==='default'?'Default':s.replaceAll('-',' ').replace(/^./,x=>x.toUpperCase());
const counts=()=>{const active=db.guests.filter(g=>g.status!=='cancelled');return{total:active.reduce((s,g)=>s+g.size,0),inside:active.filter(g=>g.status==='in').reduce((s,g)=>s+g.size,0),paid:active.filter(g=>g.type==='Stag'&&g.paid).reduce((s,g)=>s+g.size*2000,0),due:active.filter(g=>g.type==='Stag'&&!g.paid).reduce((s,g)=>s+g.size*2000,0)}};
function applyTheme(){if(ui.theme==='system')delete document.documentElement.dataset.theme;else document.documentElement.dataset.theme=ui.theme;localStorage.setItem('skipit-theme',ui.theme)}
function stopCamera(){if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}}
function go(screen,state='default',role=ui.role){stopCamera();ui.role=role;ui.screen=screen;ui.state=state;ui.search='';ui.filter='All';closeModal();render()}
function role(r){go(Object.keys(catalog[r])[0],'default',r)}
function render(){applyTheme();const roleInfo={promoter:['Promoter','Run the night','calendar'],bouncer:['Door staff','Keep the line moving','scan'],guest:['Guest','Get on the list','ticket'],system:['Design system','The foundations','layers']};
$('#studio').innerHTML=`<header class="studio-header"><div class="studio-title">${brand()}<div class="divider"></div><p>Guestlists, sorted.</p></div><div class="row"><span class="badge">MOBILE WEB · MVP 01</span><div class="theme-toggle" aria-label="Color theme">${[['system','monitor'],['light','sun'],['dark','moon']].map(([t,i])=>`<button data-action="theme" data-value="${t}" class="${ui.theme===t?'active':''}" aria-label="${t} theme" aria-pressed="${ui.theme===t}">${icon(i)}</button>`).join('')}</div></div></header><div class="mobile-tools"><span>SKIPIT · PROTOTYPE</span><select aria-label="Experience" data-change="role">${Object.entries(roleInfo).map(([r,v])=>`<option value="${r}" ${ui.role===r?'selected':''}>${v[0]}</option>`).join('')}</select><button data-action="review">Screens ${icon('layers')}</button><button data-action="theme-cycle" aria-label="Change theme">${icon(ui.theme==='dark'?'moon':ui.theme==='light'?'sun':'monitor')}</button></div><div class="studio-layout"><aside class="studio-nav"><p class="eyebrow">Explore the experience</p>${Object.entries(roleInfo).map(([r,[title,sub,i]])=>`<button class="role-button ${ui.role===r?'active':''}" data-action="role" data-value="${r}">${icon(i)}<span><strong>${title}</strong><small>${sub}</small></span></button>`).join('')}<div class="nav-bottom"><p class="eyebrow">Built for the night</p><div class="nav-note">One guestlist.<br>Every person in sync.<br>A little less chaos.</div><a href="assets/skipit-design-kit.zip" download>${icon('download')} Download design kit</a><button class="text-button" style="margin-left:12px" data-action="reset">Reset demo</button></div></aside><section class="preview-area"><div class="preview-heading"><strong>${roleInfo[ui.role][0]} <span class="muted">/ ${screens()[ui.screen]}</span></strong><span>390–430 · Responsive</span></div><div class="phone-frame"><div class="phone-top"><span>9:41</span><span class="signals">${icon('wifi')}${icon('battery')}</span></div><main class="app-scroll" id="app" aria-label="${roleInfo[ui.role][0]} app">${screenContent()}</main>${bottomNav()}<div class="phone-footer"></div></div><p class="preview-caption">DESIGNED FOR MUMBAI NIGHTS &nbsp; / &nbsp; ALL TIMES IST</p></section><aside class="review-panel">${reviewContent()}</aside></div>`;
if(ui.screen==='pass'&&!['checked-in','cancelled','event-cancelled','night-over','loading','error'].includes(ui.state))drawQR();
}
function reviewContent(){return `<p class="eyebrow">Interactive prototype</p><h3>${screens()[ui.screen]}</h3><p>${screenDescription()}</p><label for="screen-picker">Screen</label><select id="screen-picker" data-change="screen">${Object.entries(screens()).map(([s,n])=>`<option value="${s}" ${s===ui.screen?'selected':''}>${n}</option>`).join('')}</select><label for="state-picker">State</label><select id="state-picker" data-change="state">${stateList().map(s=>`<option value="${s}" ${s===ui.state?'selected':''}>${pretty(s)}</option>`).join('')}</select><div class="rule"></div><p class="eyebrow">Design notes</p><div class="note-item"><span class="note-number">01</span><span>Color carries meaning. Every status includes a word or an icon.</span></div><div class="note-item"><span class="note-number">02</span><span>44px minimum tap targets. Clear hierarchy. No hunting through menus.</span></div><div class="note-item"><span class="note-number">03</span><span>Light and dark themes follow your phone. Override above to compare.</span></div><div class="rule"></div>${chip('Sample data · local demo')}<p class="mt-sm">Changes stay in this browser. SMS, scanning and payments are simulations. No live admission or payment is processed.</p>`}
function screenDescription(){return {home:'The night at a glance. Your numbers, upcoming nights, and the list that’s live.',event:ui.role==='guest'?'From a WhatsApp link to a pass. No account. No password.':'A live headcount, quick guest actions, and one link to share.',verdict:'One decision at a time. Readable at arm’s length in a dark club.',pass:'Everything a guest needs at the door, in one private link.',tokens:'A restrained system with meaningful status color in both themes.',scanner:'One scanner for every promoter list at the same club.'}[ui.screen]||'Try the controls in the screen, then explore its alternate states.'}
function bottomNav(){if(ui.role==='promoter'&&!['auth','otp','create','add'].includes(ui.screen)){return `<nav class="bottom-nav" aria-label="Promoter navigation">${[['home','home','Overview'],['events','calendar','Events'],['book','users','Guests'],['money','wallet','Money']].map(([s,i,n])=>`<button data-action="go" data-value="${s}" class="${(ui.screen===s||(s==='events'&&['event','staff'].includes(ui.screen)))?'active':''}" aria-current="${ui.screen===s?'page':'false'}">${icon(i)}${n}</button>`).join('')}</nav>`}return''}
const appWrap=s=>`<div class="app-content">${s}</div>`;
const appHeader=()=>`<div class="app-header">${brand()}<button class="avatar" data-action="go" data-value="settings" aria-label="Open settings">${esc(initials(db.profile.name))}</button></div>`;
const back=(to,label='Back')=>`<div class="backbar">${textButton(icon('back')+label,'go',`data-value="${to}"`)}</div>`;
const art=()=>`<div class="event-art"><div class="art-top"><span>SKIPIT PRESENTS</span><span>17 OCT / SAT</span></div><h2>After<br>Hours.</h2><div class="orbit" aria-hidden="true"></div><span class="vertical">MUMBAI · VOL. 08</span></div>`;
function empty(title,body,act='',label='',i='users'){return `<div class="empty"><div class="empty-icon">${icon(i)}</div><h2>${title}</h2><p>${body}</p>${act?button(label,act):''}</div>`}
function loading(){return `<div role="status" aria-label="Loading content"><span class="sr-only">Loading…</span><div class="skeleton short"></div><div class="skeleton big"></div><div class="skeleton block"></div><div class="skeleton short"></div><div class="skeleton big"></div><div class="skeleton big"></div></div>`}
function screenContent(){if(ui.state==='loading')return appWrap(back(ui.role==='bouncer'?'tonight':ui.role==='guest'?'event':'home')+loading());if(ui.state==='error')return appWrap(empty('Couldn’t load this','Your information is safe. Check your connection and try again.','retry','Try again','wifi'));
if(ui.screen==='auth'||ui.screen==='otp')return appWrap(authScreen());
if(ui.role==='promoter')return appWrap(({home:homeScreen,events:eventsScreen,create:createScreen,event:eventScreen,add:addScreen,staff:staffScreen,book:bookScreen,money:moneyScreen,settings:settingsScreen}[ui.screen]||homeScreen)());
if(ui.role==='bouncer'){if(ui.screen==='scanner')return scannerScreen();if(ui.screen==='verdict')return verdictScreen();return appWrap(tonightScreen())}
if(ui.role==='guest')return appWrap(({event:guestEventScreen,pass:passScreen,checkout:checkoutScreen}[ui.screen]||guestEventScreen)());
return appWrap(systemScreen());}
function homeScreen(){const c=counts(),all=ui.period==='all';return `${appHeader()}<div class="heading-row"><p class="greeting">Good evening, ${esc(db.profile.name.split(' ')[0])}.</p><h1>Your nights.<br>All in one place.</h1></div><div class="segmented" aria-label="Statistics period"><button data-action="period" data-value="month" class="${!all?'active':''}" aria-pressed="${!all}">This month</button><button data-action="period" data-value="all" class="${all?'active':''}" aria-pressed="${all}">All time</button></div><div class="stats-grid">${[[ui.state==='empty'?'0':all?'1,248':'186','Through the door',''],[ui.state==='empty'?'—':all?'81%':'84%','Show-up rate',''],[ui.state==='empty'?'0':all?'292':'35','No-shows',''],[ui.state==='empty'?'0':all?'32':'5','Events',''],[money(ui.state==='empty'?0:all?184000:19000+c.paid),'Collected','money good'],[money(ui.state==='empty'?0:c.due),'Still owed','money '+(ui.state==='empty'?'':'warn')]].map(([v,l,t])=>`<div class="stat ${t}"><div class="value mono">${v}</div><div class="label">${l}</div></div>`).join('')}</div><div class="section-head"><h2>Your events</h2>${textButton(icon('plus')+'Create event','go','data-value="create"')}</div>${ui.state==='empty'?empty('The night starts here','Create your first event and give your guestlist a home.','create','Create an event','calendar'):`<article class="card">${art()}<div class="event-info"><div class="between"><div><h3>After Hours</h3><p>antiSOCIAL, Lower Parel · Tonight, 9 pm</p></div>${chip('Open','','')}</div><div class="between mt-sm"><span class="counter-small">${c.inside} <span class="muted">/ ${c.total}</span> <small>in</small></span><span class="small muted">${c.total-c.inside} expected</span></div><div class="progress"><span style="width:${c.total?c.inside/c.total*100:0}%"></span></div><button class="event-link full text-button" data-action="go" data-value="event">Manage guestlist ${icon('arrow')}</button></div></article><div class="section-head"><span class="eyebrow">Up next</span></div>${eventRow('24','OCT','The Saturday Social','Bonobo, Bandra · 9 pm','26 on list')}${db.events.map(e=>eventRow(e.date.slice(-2),'OCT',e.name,e.club+' · '+e.open,'0 on list',e.id)).join('')}<div class="section-head"><span class="eyebrow">Recent</span></div>${eventRow('10','OCT','Late Checkout','antiSOCIAL · Night ended','84% showed', 'recent')}`}`}
function eventRow(day,month,title,sub,count,id='upcoming'){return `<button class="event-row" data-action="open-event" data-id="${id}"><span class="date-square"><small>${month}</small><strong>${day}</strong></span><span class="grow"><h4>${esc(title)}</h4><p>${esc(sub)}</p></span><span class="tiny-count">${count}</span>${icon('chevron')}</button>`}
function eventsScreen(){return `${appHeader()}<div class="between heading-row"><h1>Your events</h1><button class="icon-button" data-action="create" aria-label="Create event">${icon('plus')}</button></div>${ui.state==='empty'?empty('Your next big night','Set up your first guestlist in a couple of minutes.','create','Create event','calendar'):`<p class="eyebrow">Open tonight</p>${eventRow('17','OCT','After Hours','antiSOCIAL, Lower Parel','18 / 40 in','live')}<div class="section-head"><p class="eyebrow">Upcoming</p></div>${eventRow('24','OCT','The Saturday Social','Bonobo, Bandra','26 on list')}${db.events.map(e=>eventRow(e.date.slice(-2),'OCT',e.name,e.club,'0 on list',e.id)).join('')}<div class="section-head"><p class="eyebrow">Recent</p></div>${eventRow('10','OCT','Late Checkout','antiSOCIAL · Night ended','84% showed','recent')}${eventRow('03','OCT','Off The Record','Bonobo · Night ended','90% showed','recent')}`}`}
function createScreen(){return `${back('events')}<h1>Create a night.</h1><p class="muted small mt-sm">The details first. Then bring your people.</p><form id="create-form" class="mt">${ui.state==='validation'?notice('Add an event name and a club to continue.','bad','alert'):''}${field('Event name','name','text','','required maxlength="60" placeholder="e.g. After Hours"')}${field('Club / venue','club','text','','required maxlength="80" placeholder="e.g. antiSOCIAL, Lower Parel"')}${field('Event date','date','date','2026-10-24','required')}<div class="form-grid">${field('Doors open · IST','open','time','21:00','required')}${field('Doors close · IST','close','time','03:00','required')}</div><p class="muted small" style="margin-top:-9px;margin-bottom:20px">A close time earlier than opening is the next day.</p><label class="form-field"><span>Details</span><textarea name="details" placeholder="Music, dress code, or anything your guests should know.">House, disco, and a good reason to stay out. Please carry a valid photo ID.</textarea></label><div class="form-section"><h3>Entry options</h3><p class="muted small mt-sm">Prices are per person. Caps count people.</p></div><div id="entry-editors">${entryEditor('Women',0,4,0,0)}${entryEditor('Couple',0,2,0,1)}${entryEditor('Stag',2000,1,20,2)}</div>${textButton(icon('plus')+'Add entry option','add-entry')}<div class="rule"></div><button type="submit" class="button full">Create event ${icon('arrow')}</button></form>`}
function entryEditor(name,price,max,cap,index){return `<div class="entry-editor"><div class="between">${field('Entry name',`option-${index}`,'text',name,'required')}<button type="button" class="icon-button" style="border:0" data-action="remove-entry" aria-label="Remove entry option">${icon('close')}</button></div><div class="form-grid">${field('Price / person · ₹',`price-${index}`,'number',price,'min="0" required')}${field('Max group size',`max-${index}`,'number',max,'min="1" max="20" required')}</div>${field('Total capacity (optional)',`cap-${index}`,'number',cap||'','min="1" placeholder="No limit"')}</div>`}
function eventScreen(){if(ui.selectedEvent){const e=ui.selectedEvent;return `${back('events')}<p class="eyebrow">${e.recent?'Night ended':'Upcoming event'}</p><h1 class="mt-sm">${esc(e.name)}</h1><p class="muted mt-sm">${esc(e.club)}</p><div class="event-meta"><span>${icon('calendar')} ${esc(e.date||'24 Oct 2026')} · ${esc(e.open||'9 pm')} IST</span></div>${e.recent?`<div class="stats-grid">${[['84','Through door'],['84%','Show-up'],['16','No-shows']].map(([v,l])=>`<div class="stat"><div class="value">${v}</div><div class="label">${l}</div></div>`).join('')}</div>${button(icon('download')+'Export guestlist','export','secondary full mt')}`:empty('Your list is ready','Share your event link to start bringing people together.','share-created','Share on WhatsApp','ticket')}`}
const c=counts(),cancelled=ui.state==='cancelled'||db.cancelled,closed=ui.state==='list-closed'||db.closed;return `${back('events','Your events')}<div class="between"><p class="eyebrow">Sat, 17 Oct · 9 pm–3 am IST</p><button class="icon-button" style="border:0" data-action="event-menu" aria-label="Event options">${icon('more')}</button></div><h1>After Hours</h1><p class="small muted mt-sm">antiSOCIAL, Lower Parel</p>${cancelled?notice('Event cancelled · all passes are invalid.','bad','close'):closed?notice('List closed · existing passes remain valid.','','info'):''}<div class="count-card"><div class="between"><div class="big-count mono">${c.inside}<span> / ${c.total} in</span></div>${chip(cancelled?'Cancelled':closed?'List closed':'List open',cancelled?'bad':'')}</div><div class="progress"><span style="width:${c.inside/c.total*100}%"></span></div><div class="breakdown">${['Women','Couple','Stag'].map(t=>{const gs=db.guests.filter(g=>g.type===t&&g.status!=='cancelled');return `<div><p>${t}</p><strong>${gs.filter(g=>g.status==='in').reduce((s,g)=>s+g.size,0)} / ${gs.reduce((s,g)=>s+g.size,0)} in</strong></div>`}).join('')}</div></div><div class="actions-two mt">${button(icon('share')+'Share guest link','share-event','secondary')}${button(icon('shield')+'Door staff','go','tertiary','data-value="staff"')}</div><div class="section-head"><h2>Guestlist <span class="muted small">${db.guests.length} groups</span></h2>${textButton(icon('plus')+'Add guest','go','data-value="add"')}</div><div class="search">${icon('search')}<input class="field" id="guest-search" type="search" placeholder="Search name or number" aria-label="Search guests"></div><div class="filters">${['All','Coming','In','Payment due','No-show','Cancelled'].map(f=>`<button data-action="filter" data-value="${f}" class="${ui.filter===f?'active':''}">${f}</button>`).join('')}</div><div id="guest-list">${guestRows()}</div><p class="small muted mt">Group counts include every person. One check-in admits the whole group.</p>`}
function guestRows(){let rows=db.guests.filter(g=>(g.name+' '+g.phone).toLowerCase().includes(ui.search.toLowerCase())).filter(g=>ui.filter==='All'||ui.filter==='Coming'&&g.status==='coming'||ui.filter==='In'&&g.status==='in'||ui.filter==='Payment due'&&!g.paid&&g.status!=='cancelled'||ui.filter==='No-show'&&g.status==='no-show'||ui.filter==='Cancelled'&&g.status==='cancelled');if(!rows.length)return empty('No guests here',ui.search?'Try a different name or mobile number.':`No guests are marked ${ui.filter.toLowerCase()} yet.`);return rows.map(g=>`<article class="guest-row"><div class="initials">${esc(initials(g.name))}</div><div class="grow"><div class="between"><h4>${esc(g.name)}</h4>${g.status==='in'?chip('In','good','check'):g.status==='cancelled'?chip('Cancelled','bad','close'):g.status==='no-show'?chip('No-show'):chip('Coming')}</div><p>Group of ${g.size} · ${esc(g.type)}</p><a class="guest-call muted" href="tel:+91${g.phone}">${icon('phone')} ${phone(g.phone)}</a><div>${g.type==='Stag'?chip(g.paid?'Paid · '+money(g.size*2000):money(g.size*2000)+' due',g.paid?'good':'warn',g.paid?'check':'clock'):chip('Free entry')}</div></div><button class="icon-button" data-action="guest-menu" data-id="${g.id}" aria-label="Actions for ${esc(g.name)}">${icon('more')}</button></article>`).join('')}
function addScreen(){if(ui.state==='success'){const g=db.guests.find(x=>x.id===ui.selectedGuest)||db.guests.at(-1);return `${back('event')} ${empty('They’re on the list.',`${esc(g.name)} · Group of ${g.size}<br>${esc(g.type)} entry`,'send-added','Send pass on WhatsApp','check')}${button('Back to guestlist','go','secondary full','data-value="event"')}`}
return `${back('event')}<h1>Add a guest</h1><p class="small muted mt-sm">For the people who came straight to you.</p><form id="add-form" class="mt">${field('Guest name','name','text','','required placeholder="Full name" autocomplete="name"')}${phoneField()}<label class="form-field"><span>Entry option</span><select name="type" data-change="add-type"><option>Women</option><option>Couple</option><option>Stag</option></select></label>${field('Group size','size','number','1','required min="1" max="4"','Everyone enters together on one pass.')}<label class="check-field" id="paid-check" hidden><input type="checkbox" name="paid"> Already paid me directly</label>${notice('Their pass link is private. Send it only to this guest.')}<button class="button full mt" type="submit">Add to guestlist ${icon('arrow')}</button></form>`}
function staffScreen(){return `${back('event')}<h1>Door staff</h1><p class="small muted mt-sm">Give your team access to tonight’s scanner.</p><div class="mt">${notice('Door staff see entry status and group size. They never see payment amounts.','','shield')}</div><div class="section-head"><h2>Assigned to this event</h2></div>${ui.state==='empty'||!db.staff.length?empty('No door staff yet','Add a mobile number below. They’ll sign in with an SMS code.','','','shield'):db.staff.map((s,i)=>`<div class="guest-row"><div class="initials">${esc(initials(s.name||'Door Staff'))}</div><div class="grow"><h4>${esc(s.name||'Door staff')}</h4><p>${phone(s.phone)}</p><div class="row">${textButton('Send sign-in link','share-staff',`data-id="${i}"`)}${textButton('Remove','remove-staff',`data-id="${i}"`)}</div></div></div>`).join('')}<h3 class="mt">Add door staff</h3><form id="staff-form" class="mt">${phoneField()}${field('Name (optional)','name','text','','placeholder="e.g. Sameer"')}<button class="button full" type="submit">${icon('plus')} Add door staff</button></form>`}
function bookScreen(){return `${appHeader()}<h1>Your people.</h1><p class="muted small mt-sm">Every night. One guest book.</p><div class="search mt">${icon('search')}<input class="field" id="book-search" type="search" placeholder="Search name or mobile" aria-label="Search guest book"></div><div id="book-rows">${ui.state==='empty'?empty('Every regular starts here','Guests will appear here after your first event.'):bookRows()}</div>`}
function bookRows(){const unique=[...new Map(db.guests.map(g=>[g.phone,g])).values()];return unique.filter(g=>(g.name+' '+g.phone).toLowerCase().includes(ui.search.toLowerCase())).slice(0,10).map((g,i)=>{let came=[8,6,2,5,1,3,4,1,0,2][i]||1,no=[0,1,3,0,2,1,0,1,1,0][i]||0;return `<div class="profile-card"><div class="between"><div class="row"><div class="initials">${esc(initials(g.name))}</div><div><h4>${esc(g.name)}</h4><a class="guest-call text-button muted" href="tel:+91${g.phone}" style="font-size:11px">${phone(g.phone)}</a></div></div>${no>=2?chip('FLAKY','warn','alert'):came>=5?chip('REGULAR','good','check'):''}</div><div class="profile-metrics"><div><strong>${came}</strong><small>Times came</small></div><div><strong>${no}</strong><small>No-shows</small></div><div><strong>${Math.round(came/(came+no)*100)}%</strong><small>Show-up</small></div><div><strong>${g.type==='Stag'?money(came*2000):money(0)}</strong><small>Total paid</small></div></div></div>`}).join('')||empty('No matches','Try another name or mobile number.')}
function moneyScreen(){const c=counts(),zero=ui.state==='zero-owed',direct=db.guests.filter(g=>g.type==='Stag'&&g.paid&&g.status!=='cancelled'&&g.source==='direct').reduce((n,g)=>n+g.size*2000,0);return `${appHeader()}<h1>Money, clear.</h1><p class="muted small mt-sm">Know what’s in. Know what’s outstanding.</p>${ui.state==='empty'?empty('No payments yet','Paid entries will appear here, grouped by event.','','','wallet'):`<div class="total-band mt"><div><strong class="good">${money(19000+c.paid)}</strong><small>✓ Collected this month</small></div><div><strong class="${zero?'':'warn'}">${money(zero?0:c.due)}</strong><small>${zero?'Nothing owed':'◷ Still owed'}</small></div></div><div class="section-head"><h2>After Hours</h2><span class="small muted">17 Oct</span></div><div class="payment-row"><div><strong>Paid online · verified</strong><p>Razorpay confirms these payments</p></div><strong class="good">${money(c.paid-direct)}</strong></div><div class="payment-row"><div><strong>Paid you directly</strong><p>Confirmed by you</p></div><strong class="good">${money(direct)}</strong></div><div class="payment-row"><div><strong>Still owed</strong><p>${zero?'Everyone is settled':'3 groups · follow up before entry'}</p></div><strong class="${zero?'':'warn'}">${money(zero?0:c.due)}</strong></div>${button('View guests with payment due '+icon('arrow'),'view-due','secondary full mt-sm')}<div class="section-head"><h2>Late Checkout</h2><span class="small muted">10 Oct</span></div><div class="payment-row"><div><strong>Paid online · verified</strong><p>4 payments</p></div><strong class="good">₹12,000</strong></div><div class="payment-row"><div><strong>Paid you directly</strong><p>Confirmed by you · 3 payments</p></div><strong class="good">₹7,000</strong></div><div class="payment-row"><strong>Still owed</strong><strong>₹0</strong></div><div class="mt">${notice('Online payment is a future option. Sample verified payments are shown for design review.')}</div>`}`}
function settingsScreen(){return `${back('home')}<h1>Settings</h1><form id="settings-form" class="mt">${field('Display name','name','text',db.profile.name,'required maxlength="50"')}${field('UPI ID','upi','text',db.profile.upi,'required pattern="[a-zA-Z0-9.\\-_]+@[a-zA-Z0-9]+"','Guests use this to pay you directly.')}<button class="button full" type="submit">Save changes</button></form>${ui.state==='saved'?`<div class="mt">${notice('Your settings are saved.','good','check')}</div>`:''}<div class="rule"></div><h3>Make it one tap away</h3><p class="muted small mt-sm">Add SkipIt to your Home Screen. No app download needed.</p>${button(icon('plus')+'Add to Home Screen','install','secondary full mt')}<div class="rule"></div>${button(icon('logout')+'Sign out','signout','tertiary full')}`}
function authScreen(){const isDoor=ui.role==='bouncer';if(ui.screen==='auth')return `<div class="auth-page"><div class="auth-top">${brand()}</div><p class="eyebrow">${isDoor?'Door staff':'Promoter'} sign in</p><h1 class="mt-sm">Your number.<br>You’re in.</h1><p class="muted">We’ll send a 6-digit code to your mobile.<br>No password to remember.</p><form id="phone-form">${phoneField(ui.signPhone)}${ui.state==='unknown'?notice(isDoor?`Ask the promoter to add ${phone(ui.signPhone||'9820012345')} under Door staff.`:`This number isn’t set up as a promoter yet. ${textButton('Contact SkipIt','contact')}`,'warn','info'):''}<button class="button full" type="submit">Send code ${icon('arrow')}</button></form><div class="auth-footer">Stay signed in on this phone. Sign out when using a shared device.<div class="mt">${notice('Prototype: use any valid Indian mobile number, then enter 123456. No SMS is sent.')}</div></div></div>`;
const remain=Math.max(0,Math.ceil((ui.resendAt-Date.now())/1000));return `<div class="auth-page">${back('auth','Change number')}<div class="auth-top" style="margin-bottom:45px">${brand()}</div><h1>Check your<br>messages.</h1><p class="muted">Enter the 6-digit code sent to<br><strong>${phone(ui.signPhone||'9820012345')}</strong></p><form id="otp-form"><div class="otp-boxes" aria-label="Verification code">${Array.from({length:6},(_,i)=>`<input aria-label="Code digit ${i+1}" name="digit-${i}" inputmode="numeric" type="text" pattern="[0-9]" maxlength="1" required ${i===0?'autocomplete="one-time-code"':''}>`).join('')}</div>${ui.state==='wrong-code'?notice('That code isn’t right. Check it and try again.','bad','alert'):ui.state==='expired'?notice('This code has expired. Request a new code below.','bad','clock'):''}<button class="button full" type="submit">Verify & continue ${icon('arrow')}</button></form><div class="between mt-sm"><span class="small muted" id="resend-timer">${remain?'Resend in '+remain+'s':'Didn’t get a code?'}</span><button class="text-button" data-action="resend" id="resend-button" ${remain?'disabled':''}>Resend code</button></div><p class="small muted mt">Demo code: 123456</p></div>`}
function tonightScreen(){const c=counts();let header=`<div class="app-header">${brand()}<button class="icon-button" style="border:0" data-action="door-menu" aria-label="Door staff options">${icon('more')}</button></div><p class="eyebrow">Sat, 17 Oct · Mumbai</p><h1 class="mt-sm">At the door.</h1>`;
if(ui.state==='not-added')return header+empty('You’re not on a list yet',`Ask the promoter to add<br><strong>${phone(ui.signPhone||'9820012345')}</strong><br>under Door staff.`,'retry','Refresh lists','shield');
if(ui.state==='empty')return header+empty('No lists for tonight','Your assigned lists will appear here when a promoter adds you.','retry','Refresh lists','calendar');
if(ui.state==='not-open')return header+empty('A little ahead of time.','Next: After Hours · opens 9 pm<br>antiSOCIAL, Lower Parel','retry','Refresh lists','clock');
return `${header}<p class="muted small mt-sm">One club. Every list. One scanner.</p><div class="card card-pad mt"><p class="eyebrow">antiSOCIAL · Lower Parel</p><div class="big-count mono">${c.inside+12}<span> / ${c.total+28} in</span></div><p class="small muted">Across 2 promoter lists</p><div class="progress"><span style="width:${(c.inside+12)/(c.total+28)*100}%"></span></div><div class="payment-row"><div><strong>After Hours</strong><p>Aditya Rao</p></div><strong>${c.inside} / ${c.total} in</strong></div><div class="payment-row"><div><strong>Saturday Sessions</strong><p>Rhea Shah</p></div><strong>12 / 28 in</strong></div></div>${button(icon('scan')+'Open scanner','go','full mt','data-value="scanner"')}<div class="mt">${notice('One scan admits the whole group. Ask everyone to be together before scanning.','','users')}</div><p class="muted small mt">A clear verdict will appear after every scan. Keep this page open at the door.</p>`}
function scannerScreen(){if(ui.state==='camera-denied')return appWrap(back('tonight')+empty('Camera access needed','Allow camera access in your browser’s site settings, then open the scanner again. You can also ask the promoter to check a guest in by name.','enable-camera','Try camera again','scan')+button('Try a demo scan','scan-demo-menu','secondary full'));
if(ui.state==='offline')return appWrap(back('tonight')+empty('You’re offline','A connection is needed to verify a pass. Reconnect before admitting anyone.','retry-scan','Try again','wifi'));
return `<div class="scanner"><video id="camera" autoplay playsinline muted aria-label="Camera view"></video><div class="scan-top"><div class="between"><button class="icon-button" data-action="go" data-value="tonight" aria-label="Back to tonight">${icon('back')}</button><span class="eyebrow" style="color:#aaa">antiSOCIAL · 2 lists</span></div><h2 class="mt">Scan a guest’s pass</h2><p class="mt-sm">Keep the QR inside the frame.</p></div><div><div class="scan-window">${icon('scan')}</div><p class="scan-id">ONE SCAN · WHOLE GROUP</p></div><div class="scan-bottom">${button(icon('scan')+'Enable camera','enable-camera','full')}<p>Design demo · camera previews only.<br>Choose a sample pass to try a verdict.</p>${button('Scan a sample pass','scan-demo-menu','secondary full')}</div></div>`}
const verdicts={'let-in':['LET IN','good','check','Pass checked. The whole group can enter.'],'payment-due':['PAYMENT DUE','warn','wallet','Send this guest to their promoter. Scan again after the promoter confirms.'],'scan-again':['SCAN AGAIN','warn','wifi','No signal or no answer. Reconnect and scan again before letting anyone in.'],'already-used':['ALREADY USED','bad','close','This pass was used at 11:42 pm IST. Do not admit again.'],'not-on-list':['NOT ON LIST','bad','close','This pass isn’t on an assigned list. Send the guest to the walk-in queue.'],expired:['EXPIRED','bad','clock','This pass is no longer valid. Do not admit.']};
function verdictScreen(){const key=ui.state in verdicts?ui.state:'let-in',v=verdicts[key],g=db.guests.find(g=>g.id===ui.scanGuest)||db.guests[7];return `<section class="verdict ${v[1]}" role="status" aria-live="assertive"><div><div class="between verdict-top"><span>SKIPIT · DOOR CHECK</span><span>11:48 PM IST</span></div><div class="verdict-symbol">${icon(v[2])}</div><h1>${v[0]}</h1>${!['scan-again','not-on-list','expired'].includes(key)?`<div class="person">${esc(g.name)}<p>${esc(g.type)} · Aditya’s list</p></div>${key==='let-in'?`<div class="group-count">${g.size} <small>people · admit together</small></div>`:''}`:''}<p class="explanation">${key==='already-used'?`This pass was used at ${esc(g.time||'11:42 pm')} IST. Do not admit again.`:v[3]}</p>${key==='let-in'?'<p class="small">✓ Group checked in</p>':''}</div><div>${button(key==='let-in'?'Scan next guest '+icon('arrow'):'Scan again '+icon('scan'),'go','','data-value="scanner"')}</div></section>`}
function guestEventScreen(){let top=`<div class="app-header">${brand()}<span class="small muted">Mumbai nights.</span></div>`;
const ends={'link-inactive':['This link isn’t active','Ask your promoter for the latest guestlist link.','info'],'list-closed':['The list is closed','New spots are no longer available. If you already have a pass, open your private pass link.','clock'],'already-listed':['You’re already on Aditya’s list','A pass already exists for that mobile number. Open the private link you saved, or ask Aditya to resend it. We won’t show a pass based on a phone number alone.','shield'],'night-ended':['That was a good night.','This event has ended. Ask your promoter about the next one.','clock'],'no-connection':['No connection','Check your connection, then try again. Your details haven’t been submitted.','wifi'],'event-cancelled':['This event is cancelled','After Hours will no longer take place. Contact Aditya about any payment you’ve made.','close']};
let end=ends[ui.state]||(db.cancelled?ends['event-cancelled']:db.closed?ends['list-closed']:null);if(end)return top+empty(end[0],end[1],ui.state==='no-connection'?'retry':'contact',ui.state==='no-connection'?'Try again':'Contact promoter',end[2]);
if(ui.state==='returning'||db.guestPass){const g=db.guests.find(g=>g.id===db.guestPass)||{name:'Meera Joshi',size:4,type:'Women'};return top+`<div class="guest-hero">${art()}</div><h1>After Hours</h1><p class="muted small mt-sm">Hosted by Aditya Rao · antiSOCIAL, Lower Parel</p><div class="mt">${notice('You’re on the list · '+esc(g.name),'good','check')}</div>${button('Show my pass '+icon('ticket'),'show-pass','full mt')}${button('Add someone else','add-someone','secondary full mt-sm')}<p class="muted small mt">Only a pass saved on this phone is shown here. Other guests keep their own private links.</p>`}
return `${top}<div class="guest-hero">${art()}</div><p class="eyebrow">Aditya Rao’s guestlist</p><h1 class="mt-sm">See you after hours.</h1><div class="event-meta"><span>${icon('pin')} antiSOCIAL, Lower Parel, Mumbai</span><span>${icon('calendar')} Saturday, 17 October 2026</span><span>${icon('clock')} 9 pm – 3 am IST · closes Sunday</span></div><p class="muted small">House, disco, and a good reason to stay out. Bring your people and a valid photo ID.</p><div class="rule"></div><h3>Choose your entry</h3><form id="guest-form" class="mt-sm">${[['Women','Free','Up to 4 per group'],['Couple','Free','2 people enter together'],['Stag','₹2,000 / person','20 spots total · 11 remaining']].map(([t,p,n])=>`<label class="booking-option ${ui.entry===t?'selected':''}"><input type="radio" name="entry" value="${t}" ${ui.entry===t?'checked':''}><span class="grow"><strong>${t}</strong><small>${n}</small></span><span class="price">${p}</span></label>`).join('')}${ui.state==='option-full'?notice('Stag entry just filled up. Choose another available entry option.','warn','alert'):''}<div class="between mt"><div><span class="field-label">Group size</span><small class="muted">Including you</small></div><div class="stepper"><button class="icon-button" type="button" data-action="size-minus" aria-label="Reduce group size">${icon('minus')}</button><strong id="group-size">${ui.size}</strong><button class="icon-button" type="button" data-action="size-plus" aria-label="Increase group size">${icon('plus')}</button></div></div><div class="rule"></div>${field('Your name','name','text','','required autocomplete="name" placeholder="Full name"')}${phoneField()}<div id="entry-total" class="between" style="padding:5px 0 19px"><span class="small muted">Total for your group</span><strong>${ui.entry==='Stag'?money(ui.size*2000):'Free entry'}</strong></div><button class="button full" type="submit">Get on the list ${icon('arrow')}</button><p class="muted small mt-sm">Your number is used for this guestlist and your pass. No account or SMS code needed.</p></form>`}
function activePass(){return db.guests.find(g=>g.id===db.guestPass)||(ui.state==='payment-due'?db.guests[8]:ui.state==='checked-in'?db.guests[0]:db.guests[7])}
function passScreen(){let g=activePass(),state=ui.state;if(state==='default')state=g.status==='cancelled'?'cancelled':db.cancelled?'event-cancelled':g.status==='in'?'checked-in':!g.paid?'payment-due':'on-list';let due=state==='payment-due',terminal=['checked-in','cancelled','event-cancelled','night-over'].includes(state);let passName=due&&g.type!=='Stag'?'Vihaan Desai':g.name,passType=due?'Stag':g.type,passSize=due&&g.type!=='Stag'?1:g.size,amount=passSize*2000;
const status={ 'on-list':['On the list','good','check'],'payment-due':['Payment due','warn','clock'],'checked-in':['Checked in','good','check'],cancelled:['Pass cancelled','bad','close'],'event-cancelled':['Event cancelled','bad','close'],'night-over':['Night over','','clock']}[state]||['On the list','good','check'];
return `<div class="app-header">${brand()}<span class="small muted">Your private pass</span></div><div class="pass-card"><div class="pass-head"><div class="between"><p class="eyebrow">Aditya’s guestlist</p>${chip(...status)}</div><h2 class="mt-sm">After Hours</h2><p class="small muted mt-sm">antiSOCIAL, Lower Parel<br>17 Oct · 9 pm–3 am IST</p></div><div class="pass-body">${terminal?`<div class="empty" style="padding:12px 0"><div class="empty-icon ${status[1]}">${icon(status[2])}</div><h2>${state==='checked-in'?'You’re in. Enjoy the night.':state==='cancelled'?'Your spot is cancelled.':state==='event-cancelled'?'This night is cancelled.':'Until next time.'}</h2><p>${state==='checked-in'?`Checked in at ${esc(g.time||'11:42 pm')} IST. This pass has been used.`:state==='cancelled'?'This pass no longer admits anyone.':state==='event-cancelled'?'Contact Aditya about any payment you made.':'This pass has expired. Ask your promoter about the next event.'}</p></div>`:`<div id="pass-qr" class="qr" aria-label="Demo QR code for your private pass"></div><p style="font-size:9px;letter-spacing:.08em;margin:-4px 0 20px">DEMO PASS · NOT VALID FOR ENTRY</p>`}<h2>${esc(passName)}</h2><div class="ticket-details"><div><strong>${passType}</strong><small>Entry type</small></div><div><strong>Group of ${passSize}</strong><small>Enter together</small></div></div>${!terminal?'<p>One scan lets your whole group in.</p>':''}</div></div>${due?`<div class="card card-pad mt"><div class="between"><h3 class="warn">${money(amount)} due</h3>${chip('Needs payment','warn','clock')}</div><p class="small muted mt-sm">Pay Aditya directly, then wait for confirmation. Your pass stays payment due until they mark it paid.</p><div class="between mt-sm"><div><small class="muted">UPI ID</small><p><strong>${esc(db.profile.upi)}</strong></p></div><button class="icon-button" data-action="copy-upi" aria-label="Copy UPI ID">${icon('copy')}</button></div>${button('Pay with UPI '+icon('arrow'),'upi','full mt-sm')}<div class="rule"></div><p class="eyebrow">Coming soon · online payment</p>${button('Pay now · UPI or card','go','secondary full mt-sm','data-value="checkout"')}</div>`:''}${!terminal?`${button(icon('share')+'Save to WhatsApp','save-pass','secondary full mt')}<p class="small muted mt-sm">Keep this link private. The first valid scan admits your group.</p><div class="mt">${textButton('Can’t make it? Cancel my spot','cancel-pass')}</div>`:`${button('Back to event','go','secondary full mt','data-value="event"')}`}`}
function drawQR(){const el=$('#pass-qr');if(!el)return;const q=qrcode(0,'M');q.addData(passURL(activePass()));q.make();el.innerHTML=q.createSvgTag({cellSize:4,margin:4,scalable:true});const svg=$('svg',el);svg.style.width='100%';svg.style.height='100%';svg.setAttribute('aria-hidden','true')}
function checkoutScreen(){const n=activePass().type==='Stag'?activePass().size:1;return `${back('pass','Your pass')}<p class="eyebrow">Future flow · Razorpay</p><h1 class="mt-sm">Pay for your entry.</h1><div class="card card-pad mt"><div class="between"><span>After Hours · Stag × ${n}</span><strong>${money(n*2000)}</strong></div><p class="small muted mt-sm">Payment is verified automatically.</p></div>${ui.state==='processing'?loading()+notice('Confirming payment. Keep this page open.'):ui.state==='success'?empty('Payment confirmed','Your entry is paid. Your pass is ready for the door.','paid-demo-pass','Show my pass','check'):ui.state==='failed'?empty('Payment didn’t go through','No payment is confirmed. Check your payment app before retrying.','checkout-retry','Try again','alert'):`<div class="mt">${notice('Design preview only. No money will be charged.')}</div><div class="mt stack">${button('UPI · Pay with any UPI app','checkout-upi','secondary full')}${button('Credit or debit card','checkout-card','secondary full')}</div><p class="muted small mt">The production version opens Razorpay’s secure checkout. Card details are never entered or stored by SkipIt.</p>`}`}
function systemScreen(){const top=`<p class="eyebrow">SkipIt / Design system</p><h1 class="mt-sm">${catalog.system[ui.screen]}</h1><div class="filters">${Object.entries(catalog.system).map(([s,n])=>`<button data-action="go" data-value="${s}" class="${s===ui.screen?'active':''}">${n}</button>`).join('')}</div>`;
if(ui.screen==='tokens')return top+`<p class="muted small mt">Calm by default. Color when it counts.</p><div class="section-head"><h2>01 / Surface & type</h2></div><div class="design-swatch-grid">${[['Canvas','--bg'],['Surface','--surface'],['Raised','--raised'],['Primary text','--ink'],['Secondary text','--muted'],['Divider','--line']].map(([n,v])=>`<div class="swatch"><div style="background:var(${v})"></div><small>${n}<br><span class="muted">${v}</span></small></div>`).join('')}</div><div class="section-head"><h2>02 / Status, with purpose</h2></div><div class="stack-sm">${notice('Good / done — paid, checked in, collected.','good','check')}${notice('Action needed — due, flaky, scan again.','warn','alert')}${notice('Stop — invalid, cancelled, already used.','bad','close')}</div><p class="small muted mt-sm">Pink #FF2D7B is reserved for the SkipIt logo. No gradients. No decorative accent color.</p><div class="section-head"><h2>03 / Typography</h2></div><div class="type-spec"><small>Archivo · 700 · 54–64px · −6%</small><div style="font:700 54px var(--heading);letter-spacing:-.06em">18 / 40</div></div><div class="type-spec"><small>Archivo · 700 · 34px · −4.5%</small><h1>Ready for tonight.</h1></div><div class="type-spec"><small>Archivo · 650 · 24px · −4.5%</small><h2>Every person counts.</h2></div><div class="type-spec"><small>DM Sans · 400 · 14px / 1.5</small><p>One scan lets your whole group in.</p></div><div class="type-spec"><small>DM Sans · 600 · 12px / 1.5</small><p class="small">Supporting text stays clear.</p></div><div class="section-head"><h2>04 / Layout</h2></div>${[['Spacing','4 / 8 / 12 / 16 / 24 / 32'],['Mobile width','360–430 px'],['Content gutter','21–22 px'],['Minimum touch target','44 × 44 px'],['Control height','48 px'],['Corner radius','8 / 12 / 16 px'],['Body contrast','WCAG AA · ≥ 4.5:1'],['Theme default','Device preference']].map(([a,b])=>`<div class="spec-row"><strong>${a}</strong><span>${b}</span></div>`).join('')}<a class="button secondary full mt" href="assets/tokens.json" download>${icon('download')}Download tokens</a>`;
if(ui.screen==='components')return top+`<div class="section-head"><h2>Buttons</h2></div><div class="stack-sm">${button('Primary action '+icon('arrow'),'component-demo','full')}${button('Secondary action','component-demo','secondary full')}${button('Unavailable','component-demo','full','disabled')}${button('Cancel event','component-demo','danger full')}</div><div class="section-head"><h2>Inputs</h2></div>${field('Guest name','sample-name','text','Aanya Shah')}${phoneField('9820012345')}<div class="section-head"><h2>Status chips</h2></div><div class="row" style="flex-wrap:wrap">${chip('Paid','good','check')}${chip('Payment due','warn','clock')}${chip('Cancelled','bad','close')}${chip('No-show')}</div><div class="section-head"><h2>Guest row</h2></div><div class="guest-row"><div class="initials">AS</div><div class="grow"><h4>Aanya Shah</h4><p>Group of 4 · Women</p>${chip('Checked in','good','check')}</div><button class="icon-button" data-action="guest-menu" data-id="1" aria-label="Guest actions">${icon('more')}</button></div><div class="section-head"><h2>Stat tiles</h2></div><div class="stats-grid"><div class="stat"><div class="value">186</div><div class="label">Through the door</div></div><div class="stat"><div class="value">84%</div><div class="label">Show-up rate</div></div><div class="stat"><div class="value">35</div><div class="label">No-shows</div></div></div><div class="section-head"><h2>Pass & verdict</h2></div>${button(icon('ticket')+'Open QR pass card','component-pass','secondary full')}${button(icon('scan')+'Open full-screen verdict','component-verdict','secondary full mt-sm')}<div class="section-head"><h2>Feedback</h2></div><div class="stack-sm">${notice('Payment confirmed.','good','check')}${notice('Scan again before admitting this group.','warn','alert')}${notice('This pass is cancelled.','bad','close')}</div>`;
if(ui.screen==='assets')return top+`<p class="small muted mt">Reconstructed as crisp geometric vectors from the supplied reference. Pink remains #FF2D7B.</p><div class="logo-display mt"><img src="assets/logo.svg" alt="Pink SkipIt symbol on black"><img src="assets/logo-pink.svg" alt="Black SkipIt symbol on pink"></div><div class="section-head"><h2>Vector masters</h2></div>${[['logo.svg','Primary logo · SVG'],['logo-pink.svg','Pink tile · SVG'],['logo-mark.svg','Symbol only · SVG'],['logo-maskable.svg','Maskable source · SVG']].map(assetLink).join('')}<div class="section-head"><h2>Home-screen icons</h2></div>${[['icon-192.png','192 × 192 · PNG'],['icon-512.png','512 × 512 · PNG'],['maskable-192.png','Maskable 192 × 192 · PNG'],['maskable-512.png','Maskable 512 × 512 · PNG'],['apple-touch-icon.png','Apple touch icon · 180 × 180']].map(assetLink).join('')}<p class="small muted mt">Maskable artwork stays inside the central safe circle. The background extends to every edge.</p><a class="button full mt" href="assets/skipit-design-kit.zip" download>${icon('download')} Download design kit</a>`;
return top+`<p class="small muted mt">Use the review panel to visit each screen and its states. All data is fictional.</p>${Object.entries(catalog).filter(([r])=>r!=='system').map(([r,ss])=>`<div class="section-head"><h2>${pretty(r)}</h2></div>${Object.entries(ss).map(([s,n])=>`<button class="event-row" data-action="inventory-go" data-role="${r}" data-value="${s}"><span class="grow"><h4>${n}</h4><p>${(r==='guest'&&s==='event'?guestEventStates:states[s]).map(pretty).join(' · ')}</p></span>${icon('chevron')}</button>`).join('')}`).join('')}<div class="rule"></div><p class="small muted">Prototype boundary: local demo state, no backend, no real SMS, payment verification, or QR admission. Production requirements are included in the handoff.</p>`}
function assetLink([f,n]){return `<a class="asset-row" href="assets/${f}" download><span>${n}</span>${icon('download')}</a>`}
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>el.classList.remove('show'),3500)}
function modal(title,body){modalPrevious=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><button class="icon-button modal-close" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button><h2 id="dialog-title">${title}</h2><div class="body">${body}</div></section></div>`;$('.modal button,.modal input,.modal select')?.focus()}
function closeModal(){const had=$('#modal-root').innerHTML;$('#modal-root').innerHTML='';if(had&&modalPrevious?.isConnected)modalPrevious.focus()}
function menuButton(label,action,id='',i='arrow',cls=''){return `<button class="menu-button ${cls}" data-action="${action}" data-id="${id}">${icon(i)}${label}</button>`}
function confirmModal(title,body,action,id='',label='Confirm'){modal(title,`<p>${body}</p>${button(label,action,'full mt',`data-id="${id}"`)}${button('Keep as is','close-modal','secondary full')}`)}
function guestMenu(id){const g=db.guests.find(x=>x.id===Number(id));ui.selectedGuest=g.id;modal(esc(g.name),`<p>Group of ${g.size} · ${esc(g.type)}<br>${phone(g.phone)}</p>${!g.paid&&g.status!=='cancelled'?menuButton('Mark paid directly','mark-paid',g.id,'check'):''}${g.status==='coming'?menuButton('Check in by name','check-in',g.id,'users'):''}${g.status!=='cancelled'?menuButton('Send pass on WhatsApp','send-pass',g.id,'share'):''}<a class="menu-button" href="tel:+91${g.phone}">${icon('phone')}Call guest</a>${g.status!=='cancelled'?menuButton('Remove from list','remove-guest',g.id,'close','bad'):''}`)}
function passURL(g){return location.origin+location.pathname+'#/guest/pass/'+encodeURIComponent(g.token)}
function eventURL(){return location.origin+location.pathname+'#/guest/event'}
function shareMessage(message,to=''){const href='https://wa.me/'+to+'?text='+encodeURIComponent(message);modal('Ready for WhatsApp',`<p>Your message is ready. Open WhatsApp to choose a recipient and send it.</p><div class="inline-note mt-sm" style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(message)}</div><a class="button full mt" href="${href}" target="_blank" rel="noopener noreferrer">${icon('share')} Open WhatsApp</a>${button('Copy message','copy-message','secondary full')}`);window.pendingMessage=message}
async function copyText(value){try{await navigator.clipboard.writeText(value);toast('Copied')}catch{modal('Copy this text',`<textarea class="field full" rows="5" readonly>${esc(value)}</textarea>`);$('.modal textarea').select()}}
function demoScan(id){const g=db.guests.find(g=>g.id===Number(id));ui.scanGuest=g.id;if(db.cancelled||g.status==='cancelled'){go('verdict','expired');return}if(g.status==='in'){go('verdict','already-used');return}if(!g.paid){go('verdict','payment-due');return}g.status='in';g.time='11:48 pm';save();go('verdict','let-in')}
async function enableCamera(){if(ui.screen!=='scanner'||ui.state!=='default')go('scanner');try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});const v=$('#camera');if(v){v.srcObject=cameraStream;toast('Camera preview enabled. Choose a sample pass to simulate scanning.')}else stopCamera()}catch{stopCamera();go('scanner','camera-denied')}}
function reset(){db=initialData();save();ui.selectedEvent=null;ui.entry='Women';ui.size=1;go('home','default','promoter');toast('Demo reset')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,v=b.dataset.value,id=b.dataset.id;
if(a==='role')return role(v);if(a==='go'){if(v==='event')ui.selectedEvent=null;if(v==='checkout'){db.guestPass=activePass().id;save()}return go(v)}if(a==='create')return go('create');if(a==='theme'){ui.theme=v;return render()}if(a==='theme-cycle'){ui.theme=['system','light','dark'][(['system','light','dark'].indexOf(ui.theme)+1)%3];return render()}if(a==='period'){ui.period=v;return render()}
if(a==='retry')return go(ui.screen);if(a==='close-modal')return closeModal();if(a==='review')return modal('Explore the design',reviewContent());
if(a==='reset')return confirmModal('Reset the demo?','This clears changes and restores the original sample guests and events.','reset-confirm','','Reset demo');if(a==='reset-confirm')return reset();
if(a==='filter'){ui.filter=v;$$('.filters button').forEach(x=>x.classList.toggle('active',x.dataset.value===v));$('#guest-list').innerHTML=guestRows();return}
if(a==='guest-menu')return guestMenu(id);
if(a==='mark-paid'){const g=db.guests.find(x=>x.id===Number(id));return confirmModal('Confirm direct payment',`Confirm that you received ${money(g.size*2000)} from ${esc(g.name)}. This is recorded as “Paid you directly · confirmed by you”.`,'paid-confirm',id,'Yes, payment received')}
if(a==='paid-confirm'){const g=db.guests.find(x=>x.id===Number(id));g.paid=true;g.source='direct';save();closeModal();render();return toast('Payment confirmed')}
if(a==='check-in'){if(db.cancelled)return toast('This event is cancelled. Passes cannot be admitted.');const g=db.guests.find(x=>x.id===Number(id));if(!g.paid)return modal('Payment is still due',`<p>Confirm ${money(g.size*2000)} has been received before checking in ${esc(g.name)}.</p>${button('Mark paid','mark-paid','full',`data-id="${g.id}"`)}`);return confirmModal('Check in the whole group?',`${esc(g.name)} · ${g.size} people · ${esc(g.type)}. Check that the whole group is at the door.`,'checkin-confirm',id,`Check in ${g.size} people`)}
if(a==='checkin-confirm'){if(db.cancelled)return toast('This event is cancelled. Passes cannot be admitted.');const g=db.guests.find(x=>x.id===Number(id));if(g.status!=='in'){g.status='in';g.time='11:48 pm';save()}closeModal();render();return toast('Group checked in')}
if(a==='remove-guest'){const g=db.guests.find(x=>x.id===Number(id));return confirmModal('Remove this guest?',`${esc(g.name)}’s private pass will be cancelled. Any payment refund must be handled separately.`,'remove-confirm',id,'Remove guest')}
if(a==='remove-confirm'){db.guests.find(x=>x.id===Number(id)).status='cancelled';save();closeModal();render();return toast('Guest removed · pass cancelled')}
if(a==='send-pass'||a==='send-added'){const g=db.guests.find(x=>x.id===Number(id||ui.selectedGuest));return shareMessage(`You’re on the list for After Hours at antiSOCIAL. ${g.type} · group of ${g.size}. Your private demo pass: ${passURL(g)}\nOne scan admits your whole group. Keep this link private.`,'91'+g.phone)}
if(a==='share-event')return shareMessage(`After Hours · antiSOCIAL, Lower Parel\nSaturday, 17 October · 9 pm–3 am IST\nGet on Aditya’s list: ${eventURL()}\nSkipIt design demo.`);
if(a==='share-created')return modal('Event created in this demo','<p>Your event is saved locally. A production event would receive its own public guest link after it is saved to the server.</p>');
if(a==='event-menu')return modal('Manage After Hours',menuButton(db.closed?'Reopen guestlist':'Close guestlist',db.closed?'reopen-list':'close-list','','shield')+menuButton('Export to spreadsheet','export','','download')+menuButton('Cancel event','cancel-event','','close','bad'));
if(a==='close-list')return confirmModal('Close the guestlist?','New signups stop. Existing passes still work at the door.','close-list-confirm','','Close guestlist');
if(a==='close-list-confirm'){db.closed=true;save();closeModal();render();return toast('Guestlist closed')}
if(a==='reopen-list'){db.closed=false;save();go('event');return toast('Guestlist reopened')}
if(a==='cancel-event')return confirmModal('Cancel After Hours?','All guest passes become invalid. Guests will see the cancellation on their pass. Contact paid guests separately to arrange refunds.','cancel-event-confirm','','Cancel event');
if(a==='cancel-event-confirm'){db.cancelled=true;save();go('event');return toast('Event cancelled')}
if(a==='export')return exportCSV();
if(a==='add-entry'){const i=Date.now();$('#entry-editors').insertAdjacentHTML('beforeend',entryEditor('',0,1,0,i));return}
if(a==='remove-entry'){if($$('.entry-editor').length<=1)return toast('Keep at least one entry option');b.closest('.entry-editor').remove();return}
if(a==='open-event'){if(id==='live'){ui.selectedEvent=null;return go('event')}ui.selectedEvent=id==='upcoming'?{name:'The Saturday Social',club:'Bonobo, Bandra',date:'24 Oct 2026',open:'9 pm'}:id==='recent'?{name:'Late Checkout',club:'antiSOCIAL',date:'10 Oct 2026',recent:true}:db.events.find(e=>e.id===id);return go('event')}
if(a==='share-staff'){const s=db.staff[Number(id)];return shareMessage(`You’re door staff for After Hours at antiSOCIAL. Sign in with +91 ${s.phone}: ${location.origin+location.pathname}#/bouncer/auth\nSkipIt design demo.`,'91'+s.phone)}
if(a==='remove-staff')return confirmModal('Remove door access?',`${esc(db.staff[Number(id)].name||phone(db.staff[Number(id)].phone))} will no longer be assigned to this event.`,'remove-staff-confirm',id,'Remove access');
if(a==='remove-staff-confirm'){db.staff.splice(Number(id),1);save();closeModal();render();return toast('Door access removed')}
if(a==='view-due'){ui.selectedEvent=null;go('event');ui.filter='Payment due';return render()}
if(a==='install')return modal('Add SkipIt to Home Screen',`<div class="stack"><div><h4>iPhone · Safari</h4><p class="mt-sm">Tap the Share button, then Add to Home Screen. Choose Add.</p></div><div><h4>Android · Chrome</h4><p class="mt-sm">Open the ⋮ menu, then Add to Home screen or Install app.</p></div></div><p class="mt">Open from your new SkipIt icon for a full-screen experience.</p>`);
if(a==='signout'){localStorage.removeItem('skipit-session-'+ui.role);return go('auth')}
if(a==='door-menu')return modal('Door staff',menuButton('Add to Home Screen','install','','plus')+menuButton('Sign out','signout','','logout'));
if(a==='resend'){ui.resendAt=Date.now()+30000;ui.state='default';render();return toast('New demo code ready: 123456')}
if(a==='contact')return modal(ui.role==='guest'?'Contact Aditya':'Contact SkipIt',`<p>${ui.role==='guest'?'Ask the promoter who shared your guestlist link for help.':'Your account must be set up by the SkipIt team. A production support contact will be provided here.'}</p>`);
if(a==='enable-camera')return enableCamera();if(a==='retry-scan')return go('scanner');
if(a==='scan-demo-menu')return modal('Scan a sample pass',`<p>Choose a fictional pass to preview its result.</p>${db.guests.slice(7,11).map(g=>menuButton(esc(g.name)+' · '+g.size+' people','scan-guest',g.id,'ticket')).join('')}${menuButton('Pass already used','scan-guest',1,'close')}${menuButton('Unknown pass','scan-state','not-on-list','close')}${menuButton('Expired pass','scan-state','expired','clock')}${menuButton('No signal / no answer','scan-state','scan-again','wifi')}`);
if(a==='scan-guest')return demoScan(id);if(a==='scan-state')return go('verdict',id);
if(a==='size-plus'||a==='size-minus'){if(ui.entry==='Couple')return toast('Couple entry is for 2 people');ui.size=Math.max(1,Math.min(ui.entry==='Women'?4:10,ui.size+(a==='size-plus'?1:-1)));$('#group-size').textContent=ui.size;$('#entry-total strong').textContent=ui.entry==='Stag'?money(ui.size*2000):'Free entry';return}
if(a==='show-pass')return go('pass');if(a==='add-someone'){db.guestPass=null;save();return go('event')}
if(a==='copy-upi')return copyText(db.profile.upi);if(a==='copy-message')return copyText(window.pendingMessage);
if(a==='save-pass'){const g=activePass();return shareMessage(`My After Hours pass · ${esc(g.name)}\n${passURL(g)}\nKeep this private. One scan admits our group.\nSkipIt design demo.`)}
if(a==='upi')return modal('Pay with UPI · demo',`<p>This is a design prototype. The sample UPI ID does not collect money. In production, this button opens the guest’s UPI app with the amount and promoter’s verified UPI ID.</p>${button('Preview payment confirmation','guest-paid-demo','full mt')}`);
if(a==='guest-paid-demo'||a==='paid-demo-pass'){let g=activePass();if(ui.state==='payment-due'&&g.type!=='Stag'){g=db.guests.find(x=>x.id===9);db.guestPass=g.id}g.paid=true;g.source=a==='paid-demo-pass'?'online':'direct';save();go('pass','on-list');return toast('Demo payment confirmed')}
if(a==='cancel-pass')return confirmModal('Cancel your spot?',`Your whole group’s pass will be cancelled. If you have paid, contact Aditya to arrange any refund.`,'cancel-pass-confirm','','Cancel my spot');
if(a==='cancel-pass-confirm'){activePass().status='cancelled';save();return go('pass','cancelled')}
if(a==='checkout-upi'||a==='checkout-card'){go('checkout','processing');setTimeout(()=>{if(ui.screen==='checkout'&&ui.state==='processing')go('checkout','success')},1200);return}
if(a==='checkout-retry')return go('checkout');if(a==='component-demo')return toast('Component interaction preview');
if(a==='component-pass')return go('pass','on-list','guest');if(a==='component-verdict')return go('verdict','let-in','bouncer');if(a==='inventory-go')return go(v,'default',b.dataset.role);
});
document.addEventListener('input',e=>{if(e.target.id==='guest-search'){ui.search=e.target.value;$('#guest-list').innerHTML=guestRows()}if(e.target.id==='book-search'){ui.search=e.target.value;$('#book-rows').innerHTML=bookRows()}if(e.target.closest('.otp-boxes')){e.target.value=e.target.value.replace(/\D/g,'').slice(-1);if(e.target.value)e.target.nextElementSibling?.focus()}});
document.addEventListener('paste',e=>{if(e.target.closest('.otp-boxes')){const text=e.clipboardData.getData('text').replace(/\D/g,'').slice(0,6);if(text.length>1){e.preventDefault();$$('.otp-boxes input').forEach((x,i)=>x.value=text[i]||'');$$('.otp-boxes input')[Math.min(text.length,5)].focus()}}});
document.addEventListener('change',e=>{const t=e.target,v=t.value;if(t.dataset.change==='role')role(v);if(t.dataset.change==='screen'){ui.selectedEvent=null;go(v)}if(t.dataset.change==='state'){stopCamera();ui.state=v;closeModal();render()}if(t.name==='entry'){ui.entry=v;ui.size=v==='Couple'?2:1;$$('.booking-option').forEach(x=>x.classList.toggle('selected',$('input',x).checked));$('#group-size').textContent=ui.size;$('#entry-total strong').textContent=v==='Stag'?money(2000):'Free entry'}if(t.dataset.change==='add-type'){const form=t.closest('form');const size=$('[name=size]',form);size.value=v==='Couple'?2:1;size.min=v==='Couple'?2:1;size.max=v==='Women'?4:v==='Couple'?2:10;$('#paid-check').hidden=v!=='Stag'}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.target.closest('.otp-boxes')&&e.key==='Backspace'&&!e.target.value)e.target.previousElementSibling?.focus();if(e.key==='Tab'&&$('.modal')){const f=$$('button:not([disabled]),a[href],input,select,textarea',$('.modal')).filter(x=>x.offsetParent!==null),first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,d=Object.fromEntries(new FormData(form)),cleanPhone=(d.phone||'').replace(/\D/g,'');if('phone' in d&&!/^[6-9]\d{9}$/.test(cleanPhone)){toast('Enter a valid 10-digit mobile number');return}if(form.id==='phone-form'){ui.signPhone=cleanPhone;ui.resendAt=Date.now()+30000;go('otp');return}
if(form.id==='otp-form'){const code=Array.from({length:6},(_,i)=>d['digit-'+i]||'').join('');if(code!=='123456')return go('otp','wrong-code');if(ui.state==='expired')return toast('Request a new code first');localStorage.setItem('skipit-session-'+ui.role,JSON.stringify({phone:ui.signPhone,signedIn:true}));go(ui.role==='bouncer'?'tonight':'home');return toast('Signed in to the demo')}
if(form.id==='create-form'){const id=String(Date.now()),options=$$('.entry-editor').map(el=>{const inputs=$$('input',el);return{name:inputs[0].value,price:Number(inputs[1].value),max:Number(inputs[2].value),cap:inputs[3].value?Number(inputs[3].value):null}});db.events.push({id,name:d.name,club:d.club,date:d.date,open:d.open,close:d.close,details:d.details,options});save();ui.selectedEvent=db.events.at(-1);go('event');return toast('Event created')}
if(form.id==='add-form'||form.id==='guest-form'){if(db.cancelled)return toast('This event has been cancelled');if(db.closed)return toast('The guestlist is closed');if(db.guests.some(g=>g.phone===cleanPhone&&g.status!=='cancelled')){if(form.id==='guest-form')return go('event','already-listed');return toast('This number is already on your list')}
const type=form.id==='add-form'?d.type:ui.entry,size=form.id==='add-form'?Number(d.size):ui.size;if(type==='Couple'&&size!==2)return toast('Couple entry requires 2 people');if(type==='Women'&&size>4)return toast('Women entry allows up to 4 people');if(type==='Stag'){const total=db.guests.filter(g=>g.type==='Stag'&&g.status!=='cancelled').reduce((a,g)=>a+g.size,0);if(total+size>20||ui.state==='option-full'){if(form.id==='guest-form')return go('event','option-full');return toast('Stag capacity is full')}}
const g={id:Date.now(),name:d.name.trim(),phone:cleanPhone,type,size,paid:type!=='Stag'||d.paid==='on',source:'direct',status:'coming',token:crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)};db.guests.push(g);if(form.id==='guest-form'){db.guestPass=g.id;save();go('pass',g.paid?'on-list':'payment-due')}else{ui.selectedGuest=g.id;save();go('add','success')}return}
if(form.id==='staff-form'){if(db.staff.some(s=>s.phone===cleanPhone))return toast('This number already has access');db.staff.push({name:d.name.trim(),phone:cleanPhone});save();render();return toast('Door staff added')}
if(form.id==='settings-form'){db.profile={name:d.name.trim(),upi:d.upi.trim()};save();go('settings','saved')}
});
function exportCSV(){const safe=v=>{let s=String(v);if(/^[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const rows=[['Name','Phone','Group size','Entry type','Status','Payment','Amount INR'],...db.guests.map(g=>[g.name,'+91 '+g.phone,g.size,g.type,g.status,g.type==='Stag'?g.paid?'Paid':'Due':'Free',g.type==='Stag'?g.size*2000:0])];const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='skipit-after-hours-guestlist.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);closeModal();toast('Guestlist exported')}
function readRoute(){const p=location.hash.replace(/^#\//,'').split('/');if(catalog[p[0]]&&catalog[p[0]][p[1]]){ui.role=p[0];ui.screen=p[1];ui.state='default';if(p[0]==='guest'&&p[1]==='pass'&&p[2]){const g=db.guests.find(x=>x.token===decodeURIComponent(p[2]));if(g){db.guestPass=g.id;save()}else{ui.screen='event';ui.state='link-inactive'}}}render()}
window.addEventListener('hashchange',readRoute);window.addEventListener('beforeunload',stopCamera);
setInterval(()=>{if(ui.screen==='otp'){const remaining=Math.max(0,Math.ceil((ui.resendAt-Date.now())/1000));const t=$('#resend-timer'),b=$('#resend-button');if(t)t.textContent=remaining?'Resend in '+remaining+'s':'Didn’t get a code?';if(b)b.disabled=remaining>0}},1000);
if('serviceWorker' in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
readRoute();
